 * 그 밖의 실패는 회차 리포트의 '실패'로만 남는다.
 */
const RESEND_ON: ReadonlySet<string> = new Set<string>([
  // TODO: 1.9.0부터 비어 있음. 재발송 기능째 걷어낼지, 아직 필요한지 확인 필요
]);

export function shouldResend(reason: string): boolean {
  return RESEND_ON.has(reason);
