import { DispatchRun } from "../domain/notification";
import { AlertPublisher } from "../messaging/eventPublisher";
import { AlertConsumer } from "../notifier/consumerWorker";
import { CustomerRepository } from "../repository/customerRepository";
import { DeliveryLogRepository } from "../repository/deliveryLogRepository";
import { OrderRepository } from "../repository/orderRepository";
import { planNotifications } from "./notificationPlanner";
import { shouldResend } from "./resendPolicy";

/** 발송 회차: 미발송 이벤트 → 알림 계획 → 발행(1배치) → 소비·문자 발송 → (재발송 대상 되돌림) → 회차 기록 */
export class DispatchService {
  private lastRunId = 0;

  constructor(
    private readonly orders: OrderRepository,
    private readonly customers: CustomerRepository,
    private readonly publisher: AlertPublisher,
    private readonly consumer: AlertConsumer,
    private readonly log: DeliveryLogRepository,
  ) {}

  runOnce(): DispatchRun {
    const runId = ++this.lastRunId;
    const events = this.orders.takePending();
    const plan = planNotifications(events, this.customers);
    const pub = this.publisher.publishRun(plan.notifications);
    const drained = this.consumer.drain(runId);
    for (const f of drained.failed) {
      if (shouldResend(f.reason)) this.orders.requeue(f.orderNo, f.kind);
    }
    const run: DispatchRun = {
      runId,
      planned: plan.notifications,
      skippedOptOut: plan.skippedOptOut,
      published: pub.accepted,
      batch: pub.batch,
      delivered: drained.delivered,
      failed: drained.failed,
    };
    this.log.saveRun(run);
    return run;
  }
}
import { Notification } from "../domain/notification";
import { CustomerRepository } from "../repository/customerRepository";
import { PendingEvent } from "../repository/orderRepository";

export interface Plan {
  notifications: Notification[];
  skippedOptOut: number;
}

/**
 * 회차에 실린 주문 이벤트를 고객 알림으로 바꾼다.
 *  - 수신 거부 고객은 제외한다.
 *  - 같은 주문·같은 이벤트가 회차 안에 여러 번 기록됐으면(운영자 재입력 등) 한 번만 알린다.
 *  - 이벤트 기록 순서를 유지한다.
 */
export function planNotifications(events: PendingEvent[], customers: CustomerRepository): Plan {
  const seen = new Set<string>();
  const notifications: Notification[] = [];
  let skippedOptOut = 0;
  for (const e of [...events].sort((a, b) => a.seq - b.seq)) {
    const customer = customers.find(e.customerId);
    if (!customer || !customer.smsOptIn) {
      skippedOptOut++;
      continue;
    }
    const id = `${e.orderNo}#${e.kind}`;
    if (seen.has(id)) continue;
    seen.add(id);
    notifications.push({ orderNo: e.orderNo, customerId: e.customerId, kind: e.kind });
  }
  return { notifications, skippedOptOut };
}
import { createHash } from "crypto";
import { normalizeMobile } from "../util/format";

export interface SmsReceipt {
  ok: boolean;
  receiptId?: string;
  reason?: string;
}

export interface SmsGateway {
  send(from: string, to: string, text: string): SmsReceipt;
}

/**
 * 문자 대행사 실패 응답 코드
 *   invalid-number  수신 번호 형식 오류(우리 쪽 검증)
 *   empty-body      본문 없음(우리 쪽 검증)
 *   E-THROTTLE      초당 발송 한도 초과
 *   E-CARRIER       통신사 일시 반려
 *   E-SPAM          통신사 스팸 차단(수신자 설정)
 */
export type SmsFailure = "invalid-number" | "empty-body" | "E-THROTTLE" | "E-CARRIER" | "E-SPAM";

/**
 * 문자 대행사 모의 게이트웨이 — 받은 문자를 번호별 수신함에 쌓는다.
 * faults: 번호(숫자 11자리)별로 다음 발송 시도들에 차례대로 돌려줄 실패 코드.
 */
export class InMemorySmsGateway implements SmsGateway {
  private readonly inboxes = new Map<string, string[]>();
  private readonly tries = new Map<string, number>();
  private readonly faults = new Map<string, string[]>();
  private sent = 0;

  constructor(faults: Record<string, string[]> = {}) {
    for (const [raw, codes] of Object.entries(faults)) {
      const number = normalizeMobile(raw);
      if (number) this.faults.set(number, [...codes]);
    }
  }

  send(from: string, to: string, text: string): SmsReceipt {
    const number = normalizeMobile(to);
    if (!number) return { ok: false, reason: "invalid-number" };
    if (text.length === 0) return { ok: false, reason: "empty-body" };
    this.tries.set(number, (this.tries.get(number) ?? 0) + 1);
    const fault = this.faults.get(number)?.shift();
    if (fault) return { ok: false, reason: fault };
    this.sent++;
    const list = this.inboxes.get(number) ?? [];
    list.push(text);
    this.inboxes.set(number, list);
    const receiptId = createHash("sha1").update(`${from}|${number}|${this.sent}|${text}`).digest("hex").slice(0, 12);
    return { ok: true, receiptId };
  }

  inbox(phone: string): string[] {
    const number = normalizeMobile(phone);
    return number ? [...(this.inboxes.get(number) ?? [])] : [];
  }

  /** 대행사에 넘긴 발송 요청 수(성공·실패 포함) */
  attempts(phone: string): number {
    const number = normalizeMobile(phone);
    return number ? this.tries.get(number) ?? 0 : 0;
  }
}

