export interface AppConfig {
  /** 고객 알림 토픽 */
  topic: string;
  /** 사내 메시지 키 네임스페이스 */
  keyNamespace: string;
  /** mqpub 실행 파일 경로 */
  mqpubBin: string;
  /** mqpub 스풀 디렉토리(MQPUB_SPOOL) */
  spoolDir: string;
  /** 문자 발신 번호 */
  senderId: string;
  /** 한 번에 읽어 올 최대 메시지 수 */
  drainLimit: number;
  /** 모의 문자 게이트웨이 장애 주입(개발·스테이징): 번호별로 차례대로 돌려줄 실패 코드 */
  smsFaults: Record<string, string[]>;
}

export function loadConfig(overrides: Partial<AppConfig> = {}): AppConfig {
  const env = process.env;
  const base: AppConfig = {
    topic: env.ALERTS_TOPIC ?? "alerts.order",
    keyNamespace: env.ALERTS_KEY_NS ?? "ntf",
    mqpubBin: env.MQPUB_BIN ?? join(process.cwd(), "vendor", "bin", "mqpub"),
    spoolDir: env.MQPUB_SPOOL ?? join(process.cwd(), "var", "spool"),
    senderId: "1588-0000",
    drainLimit: 500,
    smsFaults: {},
  };
  return { ...base, ...overrides };
}
import { DispatchRun, KIND_LABEL } from "../domain/notification";
import { CustomerRepository } from "../repository/customerRepository";
import { maskMobile, normalizeMobile, padEnd } from "../util/format";

export interface DispatchReportLine {
  orderNo: string;
  customerId: string;
  kind: string;
  status: "발송" | "미발송" | "실패";
  /** 실패 사유(대행사 응답 코드 등) */
  reason?: string;
  to: string;
}

export interface DispatchReport {
  runId: number;
  batch: number;
  planned: number;
  published: number;
  delivered: number;
  failed: number;
  skippedOptOut: number;
  lines: DispatchReportLine[];
  text: string;
}

/** 운영 화면용 회차 리포트 — 계획된 알림마다 발송 여부를 보여 준다. */
export function buildDispatchReport(run: DispatchRun, customers: CustomerRepository): DispatchReport {
  const lines: DispatchReportLine[] = run.planned.map((n) => {
    const hit = run.delivered.find((d) => d.orderNo === n.orderNo && d.kind === n.kind);
    const fail = run.failed.find((f) => f.orderNo === n.orderNo && f.kind === n.kind);
    const phone = normalizeMobile(customers.find(n.customerId)?.phone ?? "") ?? "";
    return {
      orderNo: n.orderNo,
      customerId: n.customerId,
      kind: KIND_LABEL[n.kind],
      status: hit ? "발송" : fail ? "실패" : "미발송",
      ...(fail && !hit ? { reason: fail.reason } : {}),
      to: maskMobile(phone),
    };
  });
  const title = `회차 ${run.runId} (배치 ${run.batch}) 계획 ${run.planned.length} / 발행 ${run.published} / 발송 ${run.delivered.length} / 실패 ${run.failed.length} / 수신거부 ${run.skippedOptOut}`;
  const body = lines.map((l) => `${padEnd(l.orderNo, 22)} ${padEnd(l.kind, 10)} ${padEnd(l.status, 6)} ${l.to}${l.reason ? ` ${l.reason}` : ""}`);
  return {
    runId: run.runId,
    batch: run.batch,
